$('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,name=form.elements.name.value.trim();settings={...settings,name,motion:form.elements.motion.checked,compact:form.elements.compact.checked,onboarded:true};const ok=storage.set('settings',settings);document.body.classList.toggle('compact',settings.compact);document.body.classList.toggle('motion-off',settings.motion);document.documentElement.classList.toggle('motion-off',settings.motion);$('.user .small').textContent=savedRoom?.playerName||name||'Gast';$('#settings-status').textContent=ok?'Gespeichert. Diese Ansicht gilt auf diesem Gerät.':'Speichern nicht möglich. Bitte lokalen Browserspeicher erlauben.';toast(ok?'Einstellungen gespeichert.':'Lokaler Speicher ist blockiert.')});
