function connection(){let bar=$('.connection-bar');if(!navigator.onLine){if(!bar){bar=document.createElement('div');bar.className='connection-bar';bar.setAttribute('role','status');bar.innerHTML='Du bist offline. Dein gespeicherter Room-Code bleibt erhalten. <a href="offline.html">Verbindungshilfe →</a>';$('.shell').prepend(bar)}}else if(bar){bar.remove();toast('Die Internetverbindung ist wieder da.')}}window.addEventListener('offline',connection);window.addEventListener('online',connection);connection();
document.addEventListener('pointermove',e=>{
  if(settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches||matchMedia('(pointer: coarse)').matches)return;
  const card=e.target.closest('.cover');
  if(card){const r=card.getBoundingClientRect();card.style.setProperty('--mx',(e.clientX-r.left)+'px');card.style.setProperty('--my',(e.clientY-r.top)+'px')}
  const hero=e.target.closest('.detail-hero');
  if(hero){const r=hero.getBoundingClientRect();const dx=((e.clientX-r.left)/r.width-.5)*8,dy=((e.clientY-r.top)/r.height-.5)*8;hero.style.backgroundPosition=`calc(50% + ${dx}px) calc(50% + ${dy}px)`}
});
document.addEventListener('click',e=>{const a=e.target.closest('.cover-link');if(!a)return;const img=a.querySelector('.cover-art img:not(.cover-blur)');if(img)img.style.viewTransitionName='cover-transition'});
